mapper.select:
select 
from kb_async_task_profiles p
where p.profile_code = #{profileCode}

select , (select count(*) from kb_model_api_bindings b inner join kb_models m on b.model_code = m.model_code and m.is_deleted = 0 where b.async_profile_code = p.profile_code) as binding_count from kb_async_task_profiles p
and (p.profile_code like concat('%', #{keyword}, '%') or p.remark like concat('%', #{keyword}, '%'))
and p.protocol = #{protocol}
and p.status = #{status}
order by p.profile_code asc
